async function api(path,opt={},retry=true){if(!session?.access_token)throw Error('جلسة الإدارة غير موجودة');const apiUrl=API_URL+'?path='+encodeURIComponent(path)+(opt.method?'':'&__fresh='+Date.now());const r=await fetch(apiUrl,{...opt,cache:'no-store',headers:{Accept:'application/json','Content-Type':'application/json',Authorization:'Bearer '+session.access_token,...(opt.headers||{})}});const t=await r.text();let d=null;try{d=t?JSON.parse(t):null}catch{d=t}if(r.status===401&&retry&&await refresh())return api(path,opt,false);if(r.status===401){localStorage.removeItem('alban_admin_session');session=null;return login()}if(!r.ok)throw Error(d?.message||d?.error||'حدث خطأ');return d?.data??d}
