function loading(){$('content').innerHTML='<div class="card">جارٍ التحميل...</div>'}async function render(){if(page==='dashboard')return dashboard();if(page==='orders')return orders();if(page==='branches')return branches();if(page==='products')return products();if(page==='main-categories')return typeof window.renderMainCategories==='function'?window.renderMainCategories():loading();if(page==='availability')return availability();if(page==='customers')return customers();if(page==='drivers')return typeof window.renderDriverManagement==='function'?window.renderDriverManagement():drivers();if(page==='employees')return employees();if(page==='offers')return offers();if(page==='settings')return settings();if(page==='reports')return reports();if(page==='notifications')return notifications();if(page==='meta-marketing')return typeof window.metaMarketing==='function'?window.metaMarketing():loading();if(page==='meta-catalog')return metaCatalog();if(page==='siwa')return siwa()}
