async function employees(){loading();try{const [p,r,b,perm]=await Promise.all([api('profiles?select=id,full_name,phone,preferred_language&order=created_at.desc'),api('user_roles?select=id,user_id,role,branch_id,created_at'),api('branches?select=id,name_ar'),api('dashboard_permissions?select=user_id,permission_key,granted')]);const rm=new Map(r.map(x=>[x.user_id,x])),bm=new Map(b.map(x=>[x.id,x.name_ar])),pm=perm.reduce((m,x)=>{(m[x.user_id]??=[]).push(x);return m},{});const staff=p.filter(x=>rm.has(x.id));$('content').innerHTML='<div class="card"><div class="head"><h2>الموظفين والصلاحيات</h2><button class="btn light" onclick="employees()">تحديث</button></div><p class="sub">الحسابات تُدار من Supabase Auth؛ هنا نتحكم في الدور والفرع والصلاحيات.</p><table class="table"><thead><tr><th>الموظف</th><th>الهاتف</th><th>الدور</th><th>الفرع</th><th>الصلاحيات</th><th>إجراء</th></tr></thead><tbody>'+staff.map(x=>{const q=rm.get(x.id)||{};return '<tr><td><b>'+esc(x.full_name||'—')+'</b></td><td>'+esc(x.phone||'—')+'</td><td><select onchange="changeRole(\''+q.id+'\',\''+x.id+'\',this.value)">'+['admin','branch_manager','branch_employee','support'].map(v=>'<option '+(q.role===v?'selected':'')+' value="'+v+'">'+roleLabels[v]+'</option>').join('')+'</select></td><td>'+esc(bm.get(q.branch_id)||'كل الفروع')+'</td><td>'+((pm[x.id]||[]).filter(z=>z.granted).length)+'</td><td><button class="btn light" onclick="managePermissions(\''+x.id+'\')">صلاحيات</button></td></tr>'}).join('')+'</tbody></table></div>'}catch(e){err(e)}}async function changeRole(id,user,role){try{if(id)await api('user_roles?id=eq.'+id,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({role})});else await api('user_roles',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({user_id:user,role,branch_id:null})});alert('تم حفظ الدور')}catch(e){alert(e.message)}}const roleLabels={admin:'مدير النظام',branch_manager:'مدير فرع',branch_employee:'موظف فرع',support:'دعم'};const PE